 */
class Leaderboard extends Page
{
    use HasLeaderboardFilter;

    protected static string $view = 'filament.pages.leaderboard';

    protected static ?int $navigationSort = 4;

    public static function getNavigationIcon(): string|Htmlable|null
    {
        return 'heroicon-o-trophy';
    }

    public function getTitle(): string|Htmlable
    {
        return 'Classifiche';
    }

    public static function getNavigationLabel(): string
    {
        return 'Classifiche';
    }

    /**
     * @return array<class-string>
     */
    protected function getFooterWidgets(): array
    {
        return [
            DistanceLeaderboardWidget::class,
            SpeedLeaderboardWidget::class,
            ElevationLeaderboardWidget::class,
        ];
    }
}
